package com.mfg.erp.entity;
import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="erp_sales_order_line",catalog="src_erp") @Getter @Setter @NoArgsConstructor public class SalesOrderLine{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="sales_order_no")private String salesOrderNo;@Column(name="line_no")private Integer lineNo;@Column(name="material_code")private String materialCode;@Column(name="material_name")private String materialName;@Column(name="order_qty")private BigDecimal orderQty;@Column(name="unit_code")private String unitCode;@Column(name="unit_price")private BigDecimal unitPrice;@Column(name="line_amount")private BigDecimal lineAmount;@Column(name="delivery_date")private LocalDate deliveryDate;}
